SELECT * FROM wrong_question
WHERE user_id = #{userId}
ORDER BY last_wrong_time DESC

SELECT wq.* FROM wrong_question wq
INNER JOIN question q ON wq.question_id = q.id
WHERE wq.user_id = #{userId}
  AND q.is_deleted = 0

  AND q.subject_id = #{subjectId}



    AND q.quiz_type = #{quizType}



    AND q.quiz_type != 'interview'


    AND (q.quiz_type IS NULL OR (q.quiz_type != 'code' AND q.quiz_type != 'interview'))


ORDER BY wq.last_wrong_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM wrong_question wq
INNER JOIN question q ON wq.question_id = q.id
WHERE wq.user_id = #{userId}
  AND q.is_deleted = 0

  AND q.subject_id = #{subjectId}



    AND q.quiz_type = #{quizType}



    AND q.quiz_type != 'interview'


    AND (q.quiz_type IS NULL OR (q.quiz_type != 'code' AND q.quiz_type != 'interview'))

mapper.update:
UPDATE wrong_question
SET wrong_times = #{wrongTimes}, user_answer = #{userAnswer}, last_wrong_time = #{lastWrongTime}
WHERE id = #{id}
